<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { Message } from '@arco-design/web-vue'
import PageHeader from '@/components/PageHeader.vue'

interface ApiEnvelope<T> { data: T }
interface Organization { id: string; name: string }
interface Project { id: string; organizationId: string; name: string; code: string }
interface Context { organizations: Organization[]; projects: Record<string, Project[]> }
interface Catalog { id: string; parentId: string | null; name: string; sortOrder: number }
interface ApiDefinition { id: string; catalogId: string; method: string; path: string; name: string; status: string; currentVersionId: string | null; versionCount: number; updatedAt: string }
interface Parameter { name: string; type: string; required: boolean; example: string; description: string }
interface ApiVersion { id: string; versionName: string; summary: string; description: string; requestHeaders: string; requestQuery: string; requestPath: string; requestBody: string; responseBody: string; exampleResponse: string; status: string; publishedAt: string | null; createdAt: string }
interface ImportResult { format: string; importedCount: number; items: string[] }

const context = ref<Context | null>(null)
const projectId = ref('')
const catalogs = ref<Catalog[]>([])
const definitions = ref<ApiDefinition[]>([])
const selectedCatalogId = ref('')
const selectedApiId = ref('')
const versions = ref<ApiVersion[]>([])
const selectedVersionId = ref('')
const loading = ref(true)
const saving = ref(false)
const catalogDialog = ref(false)
const definitionDialog = ref(false)
const versionDialog = ref(false)
const interchangeDialog = ref(false)
const keyword = ref('')
const interchangeKind = ref<'OPENAPI' | 'CURL' | 'POSTMAN' | 'HAR'>('OPENAPI')
const specInput = ref<HTMLInputElement | null>(null)
const specFileName = ref('')
const interchangeResult = ref<ImportResult | null>(null)
const curlPreview = ref('')
const catalogForm = reactive({ name: '', parentId: '', sortOrder: 0 })
const definitionForm = reactive({ catalogId: '', method: 'GET', path: '/api/v1/orders/{orderId}', name: '', versionName: '1.0.0', summary: '', description: '', headersText: 'Authorization:string:Bearer Token', queryText: '', pathText: 'orderId:string:订单标识', requestBody: '{\n  "name": "示例"\n}', responseBody: '{\n  "code": 0,\n  "data": {}\n}' })
const versionForm = reactive({ versionName: '', summary: '' })
const interchangeForm = reactive({ catalogId: '', document: '', name: '', command: "curl -X POST 'https://api.example.com/api/v1/orders?dryRun=true' -H 'Authorization: Bearer <token>' --data-raw '{\"name\":\"示例\"}'" })

const projects = computed(() => context.value?.organizations.flatMap((organization) => context.value?.projects[organization.id] ?? []) ?? [])
const selectedProject = computed(() => projects.value.find((project) => project.id === projectId.value))
const selectedApi = computed(() => definitions.value.find((api) => api.id === selectedApiId.value))
const selectedVersion = computed(() => versions.value.find((version) => version.id === selectedVersionId.value))
const catalogMap = computed(() => new Map(catalogs.value.map((catalog) => [catalog.id, catalog])))
const apiRows = computed(() => definitions.value.filter((item) => (!selectedCatalogId.value || item.catalogId === selectedCatalogId.value) && (!keyword.value.trim() || `${item.name} ${item.method} ${item.path}`.toLowerCase().includes(keyword.value.trim().toLowerCase()))))
const methodColor = (method: string) => ({ GET: 'green', POST: 'arcoblue', PUT: 'orange', PATCH: 'purple', DELETE: 'red' }[method] ?? 'gray')
const date = (value: string | null) => value ? new Intl.DateTimeFormat('zh-CN', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '-'
const parseParams = (value: string) => { try { return JSON.parse(value) as Parameter[] } catch { return [] } }

async function read<T>(url: string, init?: RequestInit): Promise<T> { const response = await fetch(url, { credentials: 'include', ...init }); const body = await response.json().catch(() => ({})) as ApiEnvelope<T> & { message?: string }; if (!response.ok) throw new Error(body.message ?? '请求失败，请稍后重试'); return body.data }
async function mutate<T>(url: string, method: 'POST', body?: unknown): Promise<T> { const csrf = await read<{ token: string; headerName: string }>('/api/v1/auth/csrf'); return read<T>(url, { method, headers: { 'Content-Type': 'application/json', [csrf.headerName]: csrf.token }, body: JSON.stringify(body ?? {}) }) }
async function loadVersions() { versions.value = selectedApiId.value ? await read<ApiVersion[]>(`/api/v1/projects/${projectId.value}/api-design/definitions/${selectedApiId.value}/versions`) : []; selectedVersionId.value = versions.value.find((version) => version.id === selectedApi.value?.currentVersionId)?.id ?? versions.value[0]?.id ?? '' }
async function loadAssets() { const [catalogData, definitionData] = await Promise.all([read<Catalog[]>(`/api/v1/projects/${projectId.value}/api-design/catalogs`), read<ApiDefinition[]>(`/api/v1/projects/${projectId.value}/api-design/definitions`)]); catalogs.value = catalogData; definitions.value = definitionData; if (!selectedApiId.value || !definitionData.some((api) => api.id === selectedApiId.value)) selectedApiId.value = definitionData[0]?.id ?? ''; await loadVersions() }
async function load() { loading.value = true; try { context.value = await read<Context>('/api/v1/access/context'); projectId.value = projects.value[0]?.id ?? ''; await loadAssets() } catch (error) { Message.error(error instanceof Error ? error.message : '加载接口资产失败') } finally { loading.value = false } }
async function changeProject() { selectedCatalogId.value = ''; selectedApiId.value = ''; try { await loadAssets() } catch (error) { Message.error(error instanceof Error ? error.message : '加载失败') } }
function openCatalog() { Object.assign(catalogForm, { name: '', parentId: selectedCatalogId.value, sortOrder: catalogs.value.length }); catalogDialog.value = true }
async function saveCatalog() { saving.value = true; try { const catalog = await mutate<Catalog>(`/api/v1/projects/${projectId.value}/api-design/catalogs`, 'POST', { ...catalogForm, parentId: catalogForm.parentId || null }); catalogDialog.value = false; selectedCatalogId.value = catalog.id; await loadAssets(); Message.success('接口目录已创建') } catch (error) { Message.error(error instanceof Error ? error.message : '创建目录失败') } finally { saving.value = false } }
function openDefinition() { if (!catalogs.value.length) { Message.warning('请先创建接口目录'); return }; Object.assign(definitionForm, { catalogId: selectedCatalogId.value || catalogs.value[0].id, method: 'GET', path: '/api/v1/orders/{orderId}', name: '', versionName: '1.0.0', summary: '', description: '', headersText: 'Authorization:string:Bearer Token', queryText: '', pathText: 'orderId:string:订单标识', requestBody: '{\n  "name": "示例"\n}', responseBody: '{\n  "code": 0,\n  "data": {}\n}' }); definitionDialog.value = true }
function linesToParams(value: string) { return value.split('\n').map((line) => line.trim()).filter(Boolean).map((line) => { const [name, type = 'string', description = ''] = line.split(':'); return { name: name.trim(), type: type.trim() || 'string', required: true, example: '', description: description.trim() } }) }
async function saveDefinition() { saving.value = true; try { const created = await mutate<ApiDefinition>(`/api/v1/projects/${projectId.value}/api-design/definitions`, 'POST', { catalogId: definitionForm.catalogId, method: definitionForm.method, path: definitionForm.path, name: definitionForm.name, versionName: definitionForm.versionName, summary: definitionForm.summary, description: definitionForm.description, headers: linesToParams(definitionForm.headersText), query: linesToParams(definitionForm.queryText), pathParameters: linesToParams(definitionForm.pathText), requestBody: definitionForm.requestBody, responseBody: definitionForm.responseBody, exampleResponse: { statusCode: 200 } }); definitionDialog.value = false; selectedApiId.value = created.id; await loadAssets(); Message.success('接口与初始版本已创建') } catch (error) { Message.error(error instanceof Error ? error.message : '创建接口失败') } finally { saving.value = false } }
async function selectApi(id: string) { selectedApiId.value = id; await loadVersions() }
function openVersion() { if (!selectedVersion.value) return; versionForm.versionName = ''; versionForm.summary = selectedVersion.value.summary; versionDialog.value = true }
async function saveVersion() { if (!selectedApiId.value || !selectedVersion.value) return; saving.value = true; try { const base = selectedVersion.value; const created = await mutate<ApiVersion>(`/api/v1/projects/${projectId.value}/api-design/definitions/${selectedApiId.value}/versions`, 'POST', { versionName: versionForm.versionName, summary: versionForm.summary, description: base.description, headers: parseParams(base.requestHeaders), query: parseParams(base.requestQuery), pathParameters: parseParams(base.requestPath), requestBody: base.requestBody, responseBody: base.responseBody, exampleResponse: JSON.parse(base.exampleResponse || '{}') }); versionDialog.value = false; await loadAssets(); selectedVersionId.value = created.id; Message.success('版本快照已创建') } catch (error) { Message.error(error instanceof Error ? error.message : '创建版本失败') } finally { saving.value = false } }
async function publishVersion() { if (!selectedApiId.value || !selectedVersionId.value) return; try { await mutate(`/api/v1/projects/${projectId.value}/api-design/definitions/${selectedApiId.value}/versions/${selectedVersionId.value}/publish`, 'POST'); await loadAssets(); Message.success('版本已发布，在线文档已更新') } catch (error) { Message.error(error instanceof Error ? error.message : '发布失败') } }
function openInterchange() { if (!catalogs.value.length) { Message.warning('请先创建接口目录'); return }; Object.assign(interchangeForm, { catalogId: selectedCatalogId.value || catalogs.value[0].id, document: '', name: '', command: "curl -X POST 'https://api.example.com/api/v1/orders?dryRun=true' -H 'Authorization: Bearer <token>' --data-raw '{\"name\":\"示例\"}'" }); interchangeKind.value = 'OPENAPI'; specFileName.value = ''; interchangeResult.value = null; curlPreview.value = ''; interchangeDialog.value = true }
function chooseSpecFile() { specInput.value?.click() }
async function specChanged(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; if (file.size > 2 * 1024 * 1024) { Message.error('接口定义文档不能超过 2 MB'); return }; try { interchangeForm.document = await file.text(); specFileName.value = file.name; Message.success(`已读取 ${file.name}`) } catch { Message.error('读取接口文档失败') } finally { if (specInput.value) specInput.value.value = '' } }
async function importInterchange() { saving.value = true; try { const result = interchangeKind.value === 'OPENAPI' ? await mutate<ImportResult>(`/api/v1/projects/${projectId.value}/api-design/interchange/openapi/import`, 'POST', { catalogId: interchangeForm.catalogId, document: interchangeForm.document }) : await mutate<ImportResult>(`/api/v1/projects/${projectId.value}/api-design/interchange/curl/import`, 'POST', { catalogId: interchangeForm.catalogId, name: interchangeForm.name, command: interchangeForm.command }); interchangeResult.value = result; await loadAssets(); Message.success(`已导入 ${result.importedCount} 个接口资产`) } catch (error) { Message.error(error instanceof Error ? error.message : '导入接口资产失败') } finally { saving.value = false } }
async function downloadOpenApi() { try { const scope = selectedCatalogId.value ? `?catalogId=${encodeURIComponent(selectedCatalogId.value)}` : ''; const response = await fetch(`/api/v1/projects/${projectId.value}/api-design/interchange/openapi/export${scope}`, { credentials: 'include' }); if (!response.ok) { const body = await response.json().catch(() => ({})) as { message?: string }; throw new Error(body.message ?? '导出失败') }; const blob = await response.blob(); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = 'testhub-openapi.json'; link.click(); URL.revokeObjectURL(link.href); Message.success('OpenAPI 3.1 文档已导出') } catch (error) { Message.error(error instanceof Error ? error.message : '导出接口文档失败') } }
async function importPostman() { saving.value = true; try { const result = await mutate<ImportResult>('/api/v1/projects/' + projectId.value + '/api-design/interchange/postman/import', 'POST', { catalogId: interchangeForm.catalogId, document: interchangeForm.document }); interchangeResult.value = result; await loadAssets(); Message.success('已导入 ' + result.importedCount + ' 个 Postman 接口资产') } catch (error) { Message.error(error instanceof Error ? error.message : '导入 Postman Collection 失败') } finally { saving.value = false } }
async function downloadPostman() { try { const scope = selectedCatalogId.value ? '?catalogId=' + encodeURIComponent(selectedCatalogId.value) : ''; const response = await fetch('/api/v1/projects/' + projectId.value + '/api-design/interchange/postman/export' + scope, { credentials: 'include' }); if (!response.ok) { const body = await response.json().catch(() => ({})) as { message?: string }; throw new Error(body.message ?? '导出失败') }; const blob = await response.blob(); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = 'testhub-postman-collection.json'; link.click(); URL.revokeObjectURL(link.href); Message.success('Postman Collection 2.1 已导出') } catch (error) { Message.error(error instanceof Error ? error.message : '导出 Postman Collection 失败') } }
async function importHar() { saving.value = true; try { const result = await mutate<ImportResult>('/api/v1/projects/' + projectId.value + '/api-design/interchange/har/import', 'POST', { catalogId: interchangeForm.catalogId, document: interchangeForm.document }); interchangeResult.value = result; await loadAssets(); Message.success('已导入 ' + result.importedCount + ' 个 HAR 接口资产') } catch (error) { Message.error(error instanceof Error ? error.message : '导入 HAR 文档失败') } finally { saving.value = false } }
async function downloadHar() { try { const scope = selectedCatalogId.value ? '?catalogId=' + encodeURIComponent(selectedCatalogId.value) : ''; const response = await fetch('/api/v1/projects/' + projectId.value + '/api-design/interchange/har/export' + scope, { credentials: 'include' }); if (!response.ok) { const body = await response.json().catch(() => ({})) as { message?: string }; throw new Error(body.message ?? '导出失败') }; const blob = await response.blob(); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = 'testhub-api-archive.har'; link.click(); URL.revokeObjectURL(link.href); Message.success('HAR 1.2 文档已导出') } catch (error) { Message.error(error instanceof Error ? error.message : '导出 HAR 文档失败') } }
async function previewCurl() { if (!selectedApi.value) { Message.warning('请先选择一个接口'); return }; try { const result = await read<{ command: string }>(`/api/v1/projects/${projectId.value}/api-design/definitions/${selectedApi.value.id}/interchange/curl?baseUrl=${encodeURIComponent('https://api.example.com')}`); curlPreview.value = result.command; interchangeDialog.value = true } catch (error) { Message.error(error instanceof Error ? error.message : '生成 cURL 失败') } }
onMounted(load)
</script>

<template>
  <div class="page api-design-page">
    <PageHeader eyebrow="API CONTRACTS" title="接口设计与文档" description="维护项目接口目录、版本化协议与在线文档。接口定义是后续调试、Mock、自动化和导入导出的统一资产源。" action="新建接口" @action="openDefinition" />
    <section class="api-summary panel"><div><span>当前项目</span><strong>{{ selectedProject?.name ?? '未分配项目' }}</strong><small>{{ selectedProject?.code }}</small></div><a-select v-model="projectId" :style="{ width: '230px' }" @change="changeProject"><a-option v-for="project in projects" :key="project.id" :value="project.id">{{ project.name }}</a-option></a-select><div><span>接口</span><strong>{{ definitions.length }}</strong><small>{{ definitions.filter((item) => item.status === 'PUBLISHED').length }} 个已发布</small></div><div><span>接口目录</span><strong>{{ catalogs.length }}</strong><small>支持层级化组织</small></div><div><span>当前版本</span><strong>{{ selectedVersion?.versionName ?? '-' }}</strong><small>{{ selectedVersion?.status === 'PUBLISHED' ? '已发布文档' : '草稿快照' }}</small></div></section>
    <section class="api-workspace">
      <aside class="catalog-panel panel"><div class="panel-heading"><div><span class="eyebrow">API TREE</span><h3>接口目录</h3></div><a-button type="text" size="small" @click="openCatalog"><icon-plus /></a-button></div><button class="catalog-row" :class="{ selected: !selectedCatalogId }" @click="selectedCatalogId = ''"><icon-apps /> 全部接口 <small>{{ definitions.length }}</small></button><button v-for="catalog in catalogs" :key="catalog.id" class="catalog-row" :class="{ selected: selectedCatalogId === catalog.id }" @click="selectedCatalogId = catalog.id"><icon-folder /><span>{{ catalog.name }}</span><small>{{ definitions.filter((api) => api.catalogId === catalog.id).length }}</small></button><a-empty v-if="!catalogs.length" description="还没有接口目录"><template #extra><a-button type="outline" @click="openCatalog">新建目录</a-button></template></a-empty></aside>
      <section class="definition-panel panel"><div class="definition-toolbar"><div><strong>接口定义</strong><a-input-search v-model="keyword" allow-clear placeholder="搜索名称、方法或路径" :style="{ width: '235px', marginLeft: '14px' }" /></div><a-space><a-button @click="openInterchange"><icon-import /> 导入 / 导出</a-button><a-button type="primary" @click="openDefinition"><icon-plus /> 新建接口</a-button></a-space></div><a-spin :loading="loading"><button v-for="api in apiRows" :key="api.id" class="api-row" :class="{ selected: selectedApiId === api.id }" @click="selectApi(api.id)"><a-tag :color="methodColor(api.method)">{{ api.method }}</a-tag><div><strong>{{ api.name }}</strong><small>{{ api.path }} · {{ catalogMap.get(api.catalogId)?.name ?? '未分类' }}</small></div><span class="version-count">{{ api.versionCount }} 个版本</span><a-tag :color="api.status === 'PUBLISHED' ? 'green' : 'gray'">{{ api.status === 'PUBLISHED' ? '已发布' : '草稿' }}</a-tag></button><a-empty v-if="!loading && !apiRows.length" description="当前范围还没有接口定义"><template #extra><a-button type="outline" @click="openDefinition">新建接口</a-button></template></a-empty></a-spin></section>
      <section class="document-panel panel"><template v-if="selectedApi && selectedVersion"><div class="document-header"><div><a-tag :color="methodColor(selectedApi.method)">{{ selectedApi.method }}</a-tag><h2>{{ selectedApi.name }}</h2><code>{{ selectedApi.path }}</code><p>{{ selectedVersion.summary || selectedVersion.description || '暂无接口摘要。' }}</p></div><a-space><a-select v-model="selectedVersionId" :style="{ width: '115px' }"><a-option v-for="version in versions" :key="version.id" :value="version.id">{{ version.versionName }}</a-option></a-select><a-button @click="openVersion"><icon-copy /> 新版本</a-button><a-button type="primary" :disabled="selectedVersion.status === 'PUBLISHED'" @click="publishVersion"><icon-send /> 发布</a-button></a-space></div><div class="doc-tabs"><section><div class="doc-heading"><strong>请求参数</strong><span>{{ parseParams(selectedVersion.requestHeaders).length + parseParams(selectedVersion.requestQuery).length + parseParams(selectedVersion.requestPath).length }} 项</span></div><div v-for="parameter in [...parseParams(selectedVersion.requestPath), ...parseParams(selectedVersion.requestQuery), ...parseParams(selectedVersion.requestHeaders)]" :key="`${parameter.name}-${parameter.type}`" class="parameter-row"><code>{{ parameter.name }}</code><a-tag size="small">{{ parameter.type }}</a-tag><span>{{ parameter.description || '参数说明' }}</span></div><a-empty v-if="!parseParams(selectedVersion.requestHeaders).length && !parseParams(selectedVersion.requestQuery).length && !parseParams(selectedVersion.requestPath).length" description="暂无结构化参数" /></section><section><div class="doc-heading"><strong>请求体</strong><span>JSON</span></div><pre>{{ selectedVersion.requestBody || '{}' }}</pre></section><section><div class="doc-heading"><strong>响应示例</strong><span>{{ selectedVersion.status === 'PUBLISHED' ? '在线文档已发布' : '草稿预览' }}</span></div><pre>{{ selectedVersion.responseBody || '{}' }}</pre></section></div><div class="document-footer"><span>版本 {{ selectedVersion.versionName }} · 创建于 {{ date(selectedVersion.createdAt) }}</span><span v-if="selectedVersion.publishedAt">发布于 {{ date(selectedVersion.publishedAt) }}</span></div></template><a-empty v-else description="选择或创建一个接口以预览在线文档"><template #extra><a-button type="primary" @click="openDefinition">新建接口</a-button></template></a-empty></section>
    </section>
    <a-modal v-model:visible="catalogDialog" title="新建接口目录" width="520px" :ok-loading="saving" @ok="saveCatalog"><a-form :model="catalogForm" layout="vertical"><a-form-item label="目录名称" required><a-input v-model="catalogForm.name" placeholder="例如：订单服务" /></a-form-item><a-form-item label="父级目录"><a-select v-model="catalogForm.parentId" allow-clear placeholder="创建为一级目录"><a-option v-for="catalog in catalogs" :key="catalog.id" :value="catalog.id">{{ catalog.name }}</a-option></a-select></a-form-item></a-form></a-modal>
    <a-modal v-model:visible="definitionDialog" title="新建接口与初始版本" width="760px" :ok-loading="saving" @ok="saveDefinition"><a-form :model="definitionForm" layout="vertical"><div class="form-grid"><a-form-item label="接口目录" required><a-select v-model="definitionForm.catalogId"><a-option v-for="catalog in catalogs" :key="catalog.id" :value="catalog.id">{{ catalog.name }}</a-option></a-select></a-form-item><a-form-item label="HTTP 方法"><a-select v-model="definitionForm.method"><a-option v-for="method in ['GET', 'POST', 'PUT', 'PATCH', 'DELETE']" :key="method" :value="method">{{ method }}</a-option></a-select></a-form-item></div><div class="form-grid"><a-form-item label="接口名称" required><a-input v-model="definitionForm.name" placeholder="例如：查询订单详情" /></a-form-item><a-form-item label="初始版本" required><a-input v-model="definitionForm.versionName" placeholder="1.0.0" /></a-form-item></div><a-form-item label="请求路径" required><a-input v-model="definitionForm.path" placeholder="/api/v1/orders/{orderId}" /></a-form-item><a-form-item label="接口摘要"><a-input v-model="definitionForm.summary" placeholder="说明该接口的业务用途" /></a-form-item><a-form-item label="路径参数（每行：名称:类型:说明）"><a-textarea v-model="definitionForm.pathText" :auto-size="{ minRows: 2, maxRows: 4 }" /></a-form-item><a-form-item label="请求头（每行：名称:类型:说明）"><a-textarea v-model="definitionForm.headersText" :auto-size="{ minRows: 2, maxRows: 4 }" /></a-form-item><a-form-item label="请求体 JSON"><a-textarea v-model="definitionForm.requestBody" :auto-size="{ minRows: 4, maxRows: 7 }" /></a-form-item><a-form-item label="响应示例 JSON"><a-textarea v-model="definitionForm.responseBody" :auto-size="{ minRows: 4, maxRows: 7 }" /></a-form-item></a-form></a-modal>
    <a-modal v-model:visible="versionDialog" title="基于当前版本创建快照" width="520px" :ok-loading="saving" @ok="saveVersion"><a-form :model="versionForm" layout="vertical"><a-alert type="info">新版本将继承当前在线文档内容，修改能力将在后续接口编辑节点补齐。</a-alert><a-form-item label="新版本名称" required><a-input v-model="versionForm.versionName" placeholder="例如：1.1.0" /></a-form-item><a-form-item label="版本摘要"><a-input v-model="versionForm.summary" placeholder="例如：增加订单扩展字段" /></a-form-item></a-form></a-modal>
    <a-modal v-model:visible="interchangeDialog" title="导入 / 导出接口资产" width="820px" :footer="false">
      <div class="interchange-dialog">
        <a-alert type="info">导入会在写入前校验；任一接口冲突或格式错误都不会留下部分资产。</a-alert>
        <div class="interchange-actions"><a-button @click="downloadOpenApi"><icon-download /> 导出 OpenAPI 3.1</a-button><a-button @click="downloadPostman"><icon-download /> 导出 Postman Collection</a-button><a-button @click="downloadHar"><icon-download /> 导出 HAR 1.2</a-button><a-button :disabled="!selectedApi" @click="previewCurl"><icon-code /> 生成当前接口 cURL</a-button></div>
        <a-radio-group v-model="interchangeKind" type="button"><a-radio value="OPENAPI">OpenAPI / Swagger</a-radio><a-radio value="POSTMAN">Postman Collection</a-radio><a-radio value="HAR">HAR 1.2</a-radio><a-radio value="CURL">cURL</a-radio></a-radio-group>
        <a-form :model="interchangeForm" layout="vertical">
          <a-form-item label="目标接口目录" required><a-select v-model="interchangeForm.catalogId"><a-option v-for="catalog in catalogs" :key="catalog.id" :value="catalog.id">{{ catalog.name }}</a-option></a-select></a-form-item>
          <template v-if="interchangeKind === 'OPENAPI' || interchangeKind === 'POSTMAN' || interchangeKind === 'HAR'">
            <a-form-item label="接口定义文档" required extra="支持 OpenAPI 3.0/3.1、Swagger 2.0 JSON/YAML、Postman Collection 2.0/2.1 JSON 或 HAR 1.2 JSON；文件上限 2 MB。"><input ref="specInput" class="file-input" type="file" accept=".json,.yaml,.yml,.har,application/json,application/yaml,text/yaml" @change="specChanged" /><div class="spec-picker"><span>{{ specFileName || '尚未选择文件，可直接粘贴文档' }}</span><a-button @click="chooseSpecFile"><icon-upload /> 选择文件</a-button></div><a-textarea v-model="interchangeForm.document" :placeholder="interchangeKind === 'POSTMAN' ? '粘贴 Postman Collection 2.0/2.1 JSON 文档' : interchangeKind === 'HAR' ? '粘贴 HAR 1.2 JSON 文档' : '粘贴 OpenAPI 或 Swagger JSON/YAML 文档'" :auto-size="{ minRows: 10, maxRows: 16 }" /></a-form-item>
          </template>
          <template v-else>
            <a-form-item label="接口名称" extra="留空时使用方法与请求路径自动命名。"><a-input v-model="interchangeForm.name" placeholder="例如：创建订单" /></a-form-item>
            <a-form-item label="cURL 命令" required extra="支持 -X/--request、-H/--header、-d/--data-raw 等常用参数。"><a-textarea v-model="interchangeForm.command" :auto-size="{ minRows: 7, maxRows: 12 }" /></a-form-item>
          </template>
          <a-button type="primary" :loading="saving" @click="interchangeKind === 'POSTMAN' ? importPostman() : interchangeKind === 'HAR' ? importHar() : importInterchange()"><icon-import /> 校验并导入</a-button>
        </a-form>
        <section v-if="interchangeResult" class="interchange-result"><a-result status="success" :title="'已导入 ' + interchangeResult.importedCount + ' 个接口资产'" :subtitle="interchangeResult.format + ' 已写入当前项目并记录审计日志。'" /><a-space wrap><a-tag v-for="item in interchangeResult.items" :key="item" color="arcoblue">{{ item }}</a-tag></a-space></section>
        <section v-if="curlPreview" class="curl-preview"><div><strong>当前接口 cURL</strong><span>可复制到终端或 CI 配置中继续使用。</span></div><a-textarea :model-value="curlPreview" readonly :auto-size="{ minRows: 5, maxRows: 9 }" /></section>
      </div>
    </a-modal>
  </div>
</template>

